#include "adapter.hpp"
#include "dynamics_exchange.hpp"
#include <iostream>
double hinge(double x){if(x<=0)return 0.;if(x>=.01)return x-.005;double t=x/.01;return (.01-.5*x)*t*t*t;}
int main(int argc,char**argv){auto r=togt_source::read(argv[1]);auto scene=togt_source::read(argv[2]);auto vehicle=togt_source::read(argv[3]);auto meta=togt_source::read(argv[5]);togt_source::Planner planner(scene,vehicle,argv[4],true);dynamics_exchange::Model model(meta);Json out;out["reported_objective"]=r["objective"];out["gradient_inf_norm"]=r["gradient_inf_norm"];
for(int nodes:{16,32,256}){double author=0,ours=0,maxgap=0,maxspeed=0;size_t samples=0;double graderr=0;size_t gradchecks=0;for(size_t i=0;i<r["durations"].size();++i){double T=r["durations"][i];for(int k=0;k<=nodes;++k){double u=double(k)/nodes;drolib::PVAJS state=drolib::PVAJS::Zero();for(int d=0;d<=4;++d)for(int p=d;p<8;++p){double factor=1;for(int j=0;j<d;++j)factor*=p-j;for(int axis=0;axis<3;++axis)state(axis,d)+=r["coefficients"][i][p][axis].get<double>()*factor*std::pow(u,p-d)/std::pow(T,d);}Eigen::Vector3d gp,gv,ga,gj,gs;double a=planner.quad.computeRobustPenalityCost(state,Eigen::Vector3d::Zero(),planner.parameters,gp,gv,ga,gj,gs);dynamics_exchange::Vec<double> acc,jer,snap;for(int axis=0;axis<3;++axis){acc[axis]=state(axis,2);jer[axis]=state(axis,3);snap[axis]=state(axis,4);}auto res=model.residuals(acc,jer,snap);double b=0;for(int j=0;j<6;++j)b+=1000*hinge(res[j]*model.scale[j]);if(nodes==256 && a>1e-3 && gradchecks<30){for(int d=2;d<=4;++d)for(int axis=0;axis<3;++axis){auto plus=state,minus=state;double eps=1e-5*std::max(1.,std::abs(state(axis,d)));plus(axis,d)+=eps;minus(axis,d)-=eps;Eigen::Vector3d x1,x2,x3,x4,x5;double fp=planner.quad.computeRobustPenalityCost(plus,Eigen::Vector3d::Zero(),planner.parameters,x1,x2,x3,x4,x5);double fm=planner.quad.computeRobustPenalityCost(minus,Eigen::Vector3d::Zero(),planner.parameters,x1,x2,x3,x4,x5);double ad=(d==2?ga:d==3?gj:gs)[axis],fd=(fp-fm)/(2*eps);graderr=std::max(graderr,std::abs(ad-fd)/std::max({1.,std::abs(ad),std::abs(fd)}));}++gradchecks;}double w=T/nodes*((k==0||k==nodes)?.5:1.);author+=w*a;ours+=w*b;maxgap=std::max(maxgap,std::abs(a-b));maxspeed=std::max(maxspeed,state.col(1).norm());++samples;}}out[std::to_string(nodes)]={{"author_penalty_integral",author},{"ours_penalty_integral",ours},{"max_point_cost_difference",maxgap},{"samples",samples},{"author_gradient_relative_error",graderr},{"gradient_checked_nodes",gradchecks},{"max_speed",maxspeed}};}std::cout<<out.dump(2)<<std::endl;}
